"""/academyhelp (Part 7): inline help pages with Back / Home buttons. Thin handler: the pages are generated by services/academy_help.py
from game/academy_rules.py, labels live in utils/content/academy_help_texts.py.

Callback data: ach:<page>:<owner id>  (page = a key of utils.content.academy_help_texts.PAGES or "home"; at most 9 + 16 bytes, so far
below 64). The person who presses must be the owner of the menu, otherwise they get a popup and nothing is edited.

Unlike the other Academy handlers this one ignores the ACADEMY_ENABLED kill switch on purpose (documentation should stay readable);
it only adds a note when the Academy is closed. It never raises: Forbidden / BadRequest are swallowed, other errors are logged."""
from __future__ import annotations

import functools
import logging

from aiogram import F, Router
from aiogram.exceptions import TelegramBadRequest, TelegramForbiddenError
from aiogram.filters import Command, CommandObject
from aiogram.types import CallbackQuery, InlineKeyboardButton as B, InlineKeyboardMarkup, Message

from database.models import User, utcnow
from database.session import db
from game import academy_rules as AR
from keyboards.menus import kb
from services import academy_calendar as cal, academy_help as H
from utils.content import academy_help_texts as T
from utils.telegram import safe_answer, safe_edit

log = logging.getLogger(__name__)
router = Router()
PREFIX = "ach:"


def _safe(fn):
    """Never crash: Telegram refusals are logged quietly, anything else is logged loudly and answered politely."""
    @functools.wraps(fn)
    async def wrapper(event, *a, **kw):
        try:
            return await fn(event, *a, **kw)
        except (TelegramForbiddenError, TelegramBadRequest):
            log.info("academy help: telegram refused a message", exc_info=True)
        except Exception:
            log.exception("academy help handler %s failed", fn.__name__)
            try:
                if isinstance(event, CallbackQuery):
                    await safe_answer(event, T.ERROR, True)
                else:
                    await event.reply(T.ERROR)
            except Exception:
                pass
    return wrapper


# ------------------------------------------------------------------ keyboards
def data(page: str, uid: int) -> str:
    return f"{PREFIX}{page}:{uid}"


def keyboard(page: str, uid: int) -> InlineKeyboardMarkup:
    if page == T.HOME_KEY or page not in T.PAGES:
        btns = [B(text=f"{T.PAGES[k][0]} {T.PAGES[k][1]}", callback_data=data(k, uid)) for k in ("start", "daily", "exams", "adv", "social", "week", "how", "how2")]
        return kb([btns[i:i + 2] for i in range(0, len(btns), 2)])
    back, nxt = H.nav(page)
    row = []
    if back:
        row.append(B(text=T.BTN_BACK, callback_data=data(back, uid)))
    row.append(B(text=T.BTN_HOME, callback_data=data(T.HOME_KEY, uid)))
    if nxt:
        row.append(B(text=T.BTN_NEXT, callback_data=data(nxt, uid)))
    return kb([row])


# ------------------------------------------------------------------ screens
async def _week_args() -> tuple:
    """(season start, label) of the season whose times the 'week' page should show: the running one, or the next one during the
    break. (None, None) if the database is unavailable: the page then shows offsets instead of clock times."""
    try:
        now = utcnow()
        async with db.tx() as s:
            season = await cal.ensure_season(s, now)
        ph = cal.phase_at(season.start_at, now)
        if ph.key == AR.BREAK_KEY:                       # in the break ensure_season returns the OLD season: show the coming one
            return season.start_at + cal.cycle(), H.week_label(season.number + 1, None, upcoming=True)
        return season.start_at, H.week_label(season.number, season.theme)
    except Exception:
        log.warning("academy help: could not load the season", exc_info=True)
        return None, None


async def screen(page: str, uid: int) -> tuple[str, InlineKeyboardMarkup]:
    if page == "week":
        start, label = await _week_args()
        text = H.render("week", start, label)
    else:
        text = H.render(page)
    if not AR.enabled():
        text = T.CLOSED_NOTE + "\n\n" + text
    return text, keyboard(page, uid)


# ------------------------------------------------------------------ command and buttons
@router.message(Command("academyhelp"))
@_safe
async def help_cmd(m: Message, command: CommandObject, db_user: User):
    page = H.resolve(command.args)
    if page is None:
        page = T.HOME_KEY                                 # an unknown word: just show the menu
    text, markup = await screen(page, db_user.id)
    await m.reply(text, reply_markup=markup)


@router.callback_query(F.data.startswith(PREFIX))
@_safe
async def help_cb(cb: CallbackQuery):
    parts = (cb.data or "").split(":")
    if len(parts) != 3 or not parts[2].isdigit():
        return await safe_answer(cb)
    page, uid = parts[1], int(parts[2])
    if cb.from_user.id != uid:                            # owner check: someone else's menu
        return await safe_answer(cb, T.NOT_YOURS, True)
    if page != T.HOME_KEY and page not in T.PAGES:
        return await safe_answer(cb)
    text, markup = await screen(page, uid)
    await safe_edit(cb, text, markup)
    await safe_answer(cb)
